import PropTypes from 'prop-types';
import { useTheme } from '@mui/material/styles';
import { Box, Grid, Typography, FormControl, Select, MenuItem } from '@mui/material';
import Chart from 'react-apexcharts';
import MainCard from 'ui-component/cards/MainCard';
import { useState } from 'react';

const MonthlyUsersLineChart = ({ chartData }) => {
    const theme = useTheme();
    const [selectedMonth, setSelectedMonth] = useState('March');

    const months = [
        'January',
        'February',
        'March',
        'April',
        'May',
        'June',
        'July',
        'August',
        'September',
        'October',
        'November',
        'December'
    ];

    const handleMonthChange = (event) => {
        setSelectedMonth(event.target.value);
    };

    const defaultChartData = {
        height: 350,
        type: 'line',
        options: {
            chart: {
                id: 'product-trends-line',
                zoom: { enabled: false },
                toolbar: { show: false }
            },
            title: {
                text: 'Product Trends by Month',
                align: 'left',
                style: {
                    fontSize: '16px',
                    fontWeight: 'bold'
                }
            },
            dataLabels: {
                enabled: false
            },
            stroke: {
                curve: 'straight'
            },
            grid: {
                row: {
                    colors: ['#f3f3f3', 'transparent'],
                    opacity: 0.5
                },
                borderColor: theme.palette.divider
            },
            xaxis: {
                categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep'],
                axisBorder: {
                    show: true,
                    color: theme.palette.divider
                },
                axisTicks: {
                    show: true,
                    color: theme.palette.divider
                }
            },
            yaxis: {
                min: 0,
                labels: {
                    formatter: (value) => value.toFixed(0)
                }
            },
            colors: [theme.palette.primary.main]
        },
        series: [
            {
                name: 'Desktops',
                data: [10, 41, 35, 51, 49, 62, 69, 91, 148]
            }
        ]
    };

    const finalChartData = chartData || defaultChartData;

    return (
        <MainCard content={false} sx={{ background: 'white' }}>
            <Box sx={{ p: 3 }}>
                <Grid container justifyContent="space-between" alignItems="center">
                    <Grid item>
                        <Typography variant="subtitle1">{selectedMonth} Users</Typography>
                    </Grid>
                    <Grid item>
                        <FormControl variant="standard" size="small">
                            <Select value={selectedMonth} onChange={handleMonthChange} sx={{ minWidth: 120 }}>
                                {months.map((month) => (
                                    <MenuItem key={month} value={month}>
                                        {month}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                </Grid>
            </Box>
            <Chart {...finalChartData} />
        </MainCard>
    );
};

MonthlyUsersLineChart.propTypes = {
    chartData: PropTypes.shape({
        series: PropTypes.array.isRequired,
        options: PropTypes.object,
        height: PropTypes.number,
        type: PropTypes.string
    })
};

MonthlyUsersLineChart.defaultProps = {
    chartData: null
};

export default MonthlyUsersLineChart;
