import PropTypes from 'prop-types';
import { useTheme } from '@mui/material/styles';
import { Box, Grid, Typography } from '@mui/material';
import Chart from 'react-apexcharts';
import MainCard from 'ui-component/cards/MainCard';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';

const ConversionsChartCard = ({ chartData }) => {
    const theme = useTheme();

    // Default bar chart configuration if none provided
    const defaultChartData = {
        height: 350,
        type: 'bar',
        options: {
            chart: {
                id: 'monthly-stock-chart',
                toolbar: {
                    show: false
                }
            },
            plotOptions: {
                bar: {
                    borderRadius: 4,
                    columnWidth: '60%',
                    distributed: false
                }
            },
            dataLabels: {
                enabled: false
            },
            xaxis: {
                categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
                axisBorder: {
                    show: true,
                    color: theme.palette.divider
                },
                axisTicks: {
                    show: true,
                    color: theme.palette.divider
                }
            },
            yaxis: {
                min: 0,
                max: 1,
                tickAmount: 5,
                labels: {
                    formatter: (value) => value.toFixed(1)
                }
            },
            grid: {
                borderColor: theme.palette.divider
            },
            colors: [theme.palette.primary.main]
        },
        series: [
            {
                name: 'Stock Level',
                data: [0.2, 0.3, 0.4, 0.6, 0.8, 0.7, 0.5, 0.4, 0.3, 0.5, 0.6, 0.7]
            }
        ]
    };

    const finalChartData = chartData || defaultChartData;

    return (
        <MainCard content={false} sx={{ background: 'white' }}>
            <Box sx={{ p: 3 }}>
                <Grid container spacing={1} alignItems="center">
                    <Grid item>
                        <Typography variant="subtitle1">Yearly Levels</Typography>
                    </Grid>
                </Grid>
            </Box>
            <Chart {...finalChartData} />
        </MainCard>
    );
};

ConversionsChartCard.propTypes = {
    chartData: PropTypes.shape({
        series: PropTypes.array.isRequired,
        options: PropTypes.object,
        height: PropTypes.number,
        type: PropTypes.string
    })
};

ConversionsChartCard.defaultProps = {
    chartData: null
};

export default ConversionsChartCard;
