import React from 'react';
import { Box, Grid, Typography } from '@mui/material';
import { ComposableMap, Geographies, Geography } from 'react-simple-maps';

// GeoJSON for the world map
const geoUrl = 'https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json';

// Example country data
const countryData = [
    { code: 'USA', name: 'United States', percent: 12 },
    { code: 'PAK', name: 'Pakistan', percent: 8 },
    { code: 'IND', name: 'India', percent: 15 },
    { code: 'FRA', name: 'France', percent: 6 },
    { code: 'BRA', name: 'Brazil', percent: 10 },
    { code: 'CHN', name: 'China', percent: 20 },
    { code: 'DEU', name: 'Germany', percent: 5 },
    { code: 'RUS', name: 'Russia', percent: 9 },
    { code: 'AUS', name: 'Australia', percent: 4 },
    { code: 'CAN', name: 'Canada', percent: 7 },
    { code: 'JPN', name: 'Japan', percent: 11 },
    { code: 'KOR', name: 'South Korea', percent: 6 },
    { code: 'ESP', name: 'Spain', percent: 4 },
    { code: 'ITA', name: 'Italy', percent: 5 },
    { code: 'MEX', name: 'Mexico', percent: 6 },
    { code: 'IDN', name: 'Indonesia', percent: 9 },
    { code: 'TUR', name: 'Turkey', percent: 7 },
    { code: 'GBR', name: 'United Kingdom', percent: 10 },
    { code: 'EGY', name: 'Egypt', percent: 4 },
    { code: 'NGA', name: 'Nigeria', percent: 8 },
    { code: 'ARG', name: 'Argentina', percent: 6 },
    { code: 'ZAF', name: 'South Africa', percent: 5 },
    { code: 'SAU', name: 'Saudi Arabia', percent: 7 }
];
// Simple color scale based on percent
const getColor = (percent) => {
    if (percent > 15) return '#1565c0';
    if (percent > 10) return '#42a5f5';
    if (percent > 5) return '#90caf9';
    return '#e3f2fd';
};

const WorldMapWithStats = () => (
    <Grid container spacing={3}>
        {/* Left: Map */}
        <Grid item xs={12} md={6}>
            <Box sx={{ background: 'white', p: 3 }}>
                <Typography
                    component="h5"
                    sx={{
                        fontSize: { xs: '1.8rem', sm: '1.4rem', md: '1.3rem' },
                        fontWeight: 900,
                        lineHeight: 1.3,
                        marginLeft: '0rem',
                        color: '#00979D',
                        wordBreak: 'break-word',
                        textAlign: { xs: 'left', md: 'left' }
                    }}
                >
                    User by Countires
                </Typography>
            </Box>
            <Box sx={{ height: 500, background: 'white' }}>
                <ComposableMap projectionConfig={{ scale: 150 }}>
                    <Geographies geography={geoUrl}>
                        {({ geographies }) =>
                            geographies.map((geo) => {
                                const country = countryData.find((c) => c.code === geo.properties.ISO_A3);
                                return (
                                    <Geography
                                        key={geo.rsmKey}
                                        geography={geo}
                                        fill={country ? getColor(country.percent) : '#f50057'}
                                        style={{
                                            default: { outline: 'none' },
                                            hover: { fill: '#f50057', outline: 'none' },
                                            pressed: { outline: 'none' }
                                        }}
                                    />
                                );
                            })
                        }
                    </Geographies>
                </ComposableMap>
            </Box>
        </Grid>

        {/* Right: Country List in 3 Columns */}
        <Grid item xs={12} md={6}>
            <Box sx={{ background: 'white', p: 3 }}>
                <Typography
                    component="h5"
                    sx={{
                        fontSize: { xs: '1.8rem', sm: '1.4rem', md: '1.3rem' },
                        fontWeight: 900,
                        lineHeight: 1.3,
                        marginLeft: '0rem',
                        color: '#00979D',
                        wordBreak: 'break-word',
                        textAlign: { xs: 'left', md: 'left' }
                    }}
                >
                    Top 30 Countires
                </Typography>
            </Box>
            <Box display="flex" flexWrap="wrap" sx={{ columnGap: 4, rowGap: 1, background: 'white', pl: 4, pb: 4 }}>
                {countryData.map((country, index) => (
                    <Box
                        key={index}
                        sx={{ width: '30%' }} // 3 columns
                    >
                        <Typography variant="body2" sx={{ color: 'black' }}>
                            {country.name} ({country.percent}%)
                        </Typography>
                    </Box>
                ))}
            </Box>
        </Grid>
    </Grid>
);

export default WorldMapWithStats;
